import React, { useState, useRef, useEffect } from 'react';
import { pipelineService } from './pipeline_service';

const CameraRecognition = () => {
    const videoRef = useRef(null);
    const streamRef = useRef(null);
    const intervalRef = useRef(null);
    const processingRef = useRef(false);

    const [status, setStatus] = useState('inactive'); // inactive, scanning, paused
    const [lastResult, setLastResult] = useState(null);
    const [error, setError] = useState(null);
    const [stats, setStats] = useState({ frames: 0, successful: 0 });

    const startCamera = async () => {
        try {
            setError(null);
            const stream = await navigator.mediaDevices.getUserMedia({
                video: { width: 1280, height: 720, facingMode: 'user' },
                audio: false
            });

            streamRef.current = stream;
            if (videoRef.current) {
                videoRef.current.srcObject = stream;
                setStatus('scanning');
            }
        } catch (err) {
            setError("Erreur d'initialisation du peripherique video");
        }
    };

    const stopCamera = () => {
        if (intervalRef.current) clearInterval(intervalRef.current);
        if (streamRef.current) {
            streamRef.current.getTracks().forEach(track => track.stop());
        }
        setStatus('inactive');
    };

    const captureAndProcess = async () => {
        if (!videoRef.current || processingRef.current || status !== 'scanning') return;

        try {
            processingRef.current = true;

            const canvas = document.createElement('canvas');
            canvas.width = videoRef.current.videoWidth;
            canvas.height = videoRef.current.videoHeight;
            const ctx = canvas.getContext('2d');
            ctx.drawImage(videoRef.current, 0, 0);

            const base64Image = canvas.toDataURL('image/jpeg', 0.90);

            // Interaction via pipeline_service uniquement
            const response = await pipelineService.processFrame(base64Image);

            setStats(prev => ({ ...prev, frames: prev.frames + 1 }));

            if (response?.success) {
                setLastResult(response.data);
                setStats(prev => ({ ...prev, successful: prev.successful + 1 }));

                // Pause temporaire pour eviter les doublons
                setStatus('paused');
                setTimeout(() => setStatus('scanning'), 3000);
            }
        } catch (err) {
            console.error("Erreur de pipeline:", err.message);
        } finally {
            processingRef.current = false;
        }
    };

    useEffect(() => {
        if (status === 'scanning') {
            intervalRef.current = setInterval(captureAndProcess, 700);
        } else {
            if (intervalRef.current) clearInterval(intervalRef.current);
        }
        return () => {
            if (intervalRef.current) clearInterval(intervalRef.current);
        };
    }, [status]);

    return (
        <div style={styles.container}>
            <div style={styles.header}>
                <h2 style={styles.title}>Systeme de Presence Biometrique</h2>
                <div style={styles.indicatorContainer}>
                    <span style={{...styles.indicator, backgroundColor: status === 'scanning' ? '#22c55e' : '#64748b'}} />
                    <span style={styles.statusText}>{status.toUpperCase()}</span>
                </div>
            </div>

            <div style={styles.viewport}>
                <video 
                    ref={videoRef} 
                    autoPlay 
                    playsInline 
                    muted 
                    style={{...styles.video, opacity: status === 'inactive' ? 0.3 : 1}} 
                />
                {status === 'scanning' && <div style={styles.scannerOverlay} />}
                {error && <div style={styles.errorMessage}>{error}</div>}
            </div>

            <div style={styles.controls}>
                {status === 'inactive' ? (
                    <button onClick={startCamera} style={styles.buttonPrimary}>Activer la Camera</button>
                ) : (
                    <button onClick={stopCamera} style={styles.buttonSecondary}>Desactiver</button>
                )}
            </div>

            {lastResult && (
                <div style={styles.resultPanel}>
                    <div style={styles.resultHeader}>Derniere Identification</div>
                    <div style={styles.resultBody}>
                        <div style={styles.dataRow}>
                            <span style={styles.label}>Utilisateur:</span>
                            <span style={styles.value}>{lastResult.student}</span>
                        </div>
                        <div style={styles.dataRow}>
                            <span style={styles.label}>Confiance:</span>
                            <span style={styles.value}>{(lastResult.confidence * 100).toFixed(2)}%</span>
                        </div>
                    </div>
                </div>
            )}

            <div style={styles.footer}>
                Analyses effectuees: {stats.frames} | Succes: {stats.successful}
            </div>
        </div>
    );
};

const styles = {
    container: { maxWidth: '800px', margin: '40px auto', padding: '20px', backgroundColor: '#f8fafc', borderRadius: '12px', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)', fontFamily: 'Inter, system-ui, sans-serif' },
    header: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' },
    title: { fontSize: '1.25rem', fontWeight: '600', color: '#1e293b', margin: 0 },
    indicatorContainer: { display: 'flex', alignItems: 'center', gap: '8px' },
    indicator: { width: '10px', height: '10px', borderRadius: '50%' },
    statusText: { fontSize: '0.75rem', fontWeight: '700', color: '#64748b' },
    viewport: { position: 'relative', width: '100%', backgroundColor: '#000', borderRadius: '8px', overflow: 'hidden', aspectRatio: '16/9' },
    video: { width: '100%', height: '100%', objectFit: 'cover', transition: 'opacity 0.3s ease' },
    scannerOverlay: { position: 'absolute', top: 0, left: 0, width: '100%', height: '2px', background: '#3b82f6', boxShadow: '0 0 15px #3b82f6', animation: 'scan 2.5s linear infinite' },
    errorMessage: { position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#ef4444', backgroundColor: 'rgba(0,0,0,0.7)', padding: '20px', textAlign: 'center' },
    controls: { display: 'flex', justifyContent: 'center', marginTop: '20px' },
    buttonPrimary: { padding: '12px 24px', backgroundColor: '#2563eb', color: '#fff', border: 'none', borderRadius: '6px', fontWeight: '600', cursor: 'pointer' },
    buttonSecondary: { padding: '12px 24px', backgroundColor: 'transparent', color: '#475569', border: '1px solid #cbd5e1', borderRadius: '6px', fontWeight: '600', cursor: 'pointer' },
    resultPanel: { marginTop: '20px', backgroundColor: '#fff', borderRadius: '8px', border: '1px solid #e2e8f0', overflow: 'hidden' },
    resultHeader: { padding: '10px 15px', backgroundColor: '#f1f5f9', fontSize: '0.875rem', fontWeight: '600', color: '#475569' },
    resultBody: { padding: '15px' },
    dataRow: { display: 'flex', justifyContent: 'space-between', marginBottom: '8px' },
    label: { color: '#64748b', fontSize: '0.875rem' },
    value: { color: '#1e293b', fontWeight: '600', fontSize: '0.875rem' },
    footer: { marginTop: '20px', fontSize: '0.75rem', color: '#94a3b8', textAlign: 'right' }
};

// Injection CSS pour l'animation
const styleSheet = document.createElement("style");
styleSheet.innerText = `@keyframes scan { 0% { top: 0; } 100% { top: 100%; } }`;
document.head.appendChild(styleSheet);

export default CameraRecognition;
